-- =============================================================================
-- Retail Revenue & Customer Intelligence Platform
-- SQL Business Analytics Suite (Target Environment: MySQL 8.0+)
--
-- NOTE ON DATA TRANSPARENCY:
-- All metrics, findings, and recommendations generated by this script are based 
-- on 100% SYNTHETIC retail transaction data created for portfolio demonstration.
-- =============================================================================

USE retail_intelligence_db;

-- =============================================================================
-- SECTION 1: REVENUE & GROWTH ANALYTICS
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Business Question 1: What is the monthly net revenue trend and valid order volume?
-- SQL Techniques: DATE_FORMAT, Aggregations, Filter on Completed/Shipped orders
-- Logic: Excludes Cancelled/Refunded orders to calculate true net revenue and AOV.
-- Output Metrics: Month_Year, Total_Revenue, Order_Count, Monthly_AOV
-- Business Interpretation: Establishes the core revenue baseline across the 24-month horizon.
-- -----------------------------------------------------------------------------
SELECT 
    DATE_FORMAT(o.order_date, '%Y-%m') AS month_year,
    COUNT(DISTINCT o.order_id) AS total_orders,
    ROUND(SUM(o.total_amount), 2) AS total_net_revenue,
    ROUND(SUM(o.total_amount) / NULLIF(COUNT(DISTINCT o.order_id), 0), 2) AS monthly_aov
FROM orders o
WHERE o.order_status IN ('Completed', 'Shipped')
GROUP BY DATE_FORMAT(o.order_date, '%Y-%m')
ORDER BY month_year ASC;


-- -----------------------------------------------------------------------------
-- Business Question 2: What is the Month-over-Month (MoM) revenue growth percentage?
-- SQL Techniques: CTE, Window Function LAG() OVER()
-- Logic: Compares current month net revenue against prior month using LAG().
-- Output Metrics: month_year, current_month_revenue, prior_month_revenue, mom_growth_pct
-- Business Interpretation: Highlights seasonal momentum and growth spikes/slumps.
-- -----------------------------------------------------------------------------
WITH MonthlyRevenue AS (
    SELECT 
        DATE_FORMAT(order_date, '%Y-%m') AS month_year,
        SUM(total_amount) AS net_revenue
    FROM orders
    WHERE order_status IN ('Completed', 'Shipped')
    GROUP BY DATE_FORMAT(order_date, '%Y-%m')
)
SELECT 
    month_year,
    ROUND(net_revenue, 2) AS current_month_revenue,
    ROUND(LAG(net_revenue, 1) OVER (ORDER BY month_year), 2) AS prior_month_revenue,
    ROUND(
        ((net_revenue - LAG(net_revenue, 1) OVER (ORDER BY month_year)) / 
        NULLIF(LAG(net_revenue, 1) OVER (ORDER BY month_year), 0)) * 100, 
        2
    ) AS mom_growth_pct
FROM MonthlyRevenue
ORDER BY month_year ASC;


-- -----------------------------------------------------------------------------
-- Business Question 3: What is the geographical revenue breakdown by Country and State?
-- SQL Techniques: Multi-table JOIN (orders, customers), Window Function SUM() OVER()
-- Logic: Computes sales per location and geographical % contribution to total sales.
-- Output Metrics: country, state, total_customers, total_orders, location_revenue, pct_total_revenue
-- Business Interpretation: Identifies core regional markets vs underpenetrated territories.
-- -----------------------------------------------------------------------------
WITH RegionalSales AS (
    SELECT 
        c.country,
        c.state,
        COUNT(DISTINCT c.customer_id) AS active_customers,
        COUNT(DISTINCT o.order_id) AS total_orders,
        SUM(o.total_amount) AS total_revenue
    FROM orders o
    JOIN customers c ON o.customer_id = c.customer_id
    WHERE o.order_status IN ('Completed', 'Shipped')
    GROUP BY c.country, c.state
)
SELECT 
    country,
    state,
    active_customers,
    total_orders,
    ROUND(total_revenue, 2) AS location_revenue,
    ROUND((total_revenue / SUM(total_revenue) OVER()) * 100, 2) AS pct_total_revenue
FROM RegionalSales
ORDER BY location_revenue DESC;


-- -----------------------------------------------------------------------------
-- Business Question 4: How has Average Order Value (AOV) trended alongside a 3-Month Moving Average?
-- SQL Techniques: CTE, Moving Average Window Function AVG() OVER(ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)
-- Logic: Smooths out monthly AOV fluctuations to reveal structural basket size changes.
-- Output Metrics: month_year, monthly_revenue, total_orders, monthly_aov, aov_3mo_moving_avg
-- Business Interpretation: Detects whether revenue expansion is driven by pricing or order volume.
-- -----------------------------------------------------------------------------
WITH MonthlyMetrics AS (
    SELECT 
        DATE_FORMAT(order_date, '%Y-%m') AS month_year,
        SUM(total_amount) AS revenue,
        COUNT(DISTINCT order_id) AS orders_cnt,
        SUM(total_amount) / NULLIF(COUNT(DISTINCT order_id), 0) AS raw_aov
    FROM orders
    WHERE order_status IN ('Completed', 'Shipped')
    GROUP BY DATE_FORMAT(order_date, '%Y-%m')
)
SELECT 
    month_year,
    ROUND(revenue, 2) AS monthly_revenue,
    orders_cnt,
    ROUND(raw_aov, 2) AS monthly_aov,
    ROUND(
        AVG(raw_aov) OVER (
            ORDER BY month_year 
            ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
        ), 
        2
    ) AS aov_3mo_moving_avg
FROM MonthlyMetrics
ORDER BY month_year ASC;


-- -----------------------------------------------------------------------------
-- Business Question 5: What is the gross profit margin contribution by product category?
-- SQL Techniques: 4-Table JOIN (orders, order_items, products, categories), Aggregations
-- Logic: Gross Profit = Item Sales Revenue - (Product Cost Price * Quantity Sold).
-- Output Metrics: department, category_name, total_units_sold, gross_revenue, total_cost, gross_profit, gross_margin_pct
-- Business Interpretation: Reveals high-volume low-margin categories vs high-profit drivers.
-- -----------------------------------------------------------------------------
SELECT 
    cat.department,
    cat.category_name,
    SUM(oi.quantity) AS total_units_sold,
    ROUND(SUM(oi.item_total), 2) AS gross_revenue,
    ROUND(SUM(p.cost_price * oi.quantity), 2) AS total_cost,
    ROUND(SUM(oi.item_total) - SUM(p.cost_price * oi.quantity), 2) AS gross_profit,
    ROUND(
        ((SUM(oi.item_total) - SUM(p.cost_price * oi.quantity)) / NULLIF(SUM(oi.item_total), 0)) * 100, 
        2
    ) AS gross_margin_pct
FROM order_items oi
JOIN orders o ON oi.order_id = o.order_id
JOIN products p ON oi.product_id = p.product_id
JOIN categories cat ON p.category_id = cat.category_id
WHERE o.order_status IN ('Completed', 'Shipped')
GROUP BY cat.department, cat.category_name
ORDER BY gross_profit DESC;


-- =============================================================================
-- SECTION 2: CUSTOMER INTELLIGENCE & SEGMENTATION
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Business Question 6: What is the distribution of customer purchase frequency (One-Time vs Repeat Buyers)?
-- SQL Techniques: CTE, Aggregations, CASE Bucketing
-- Logic: Groups customers by distinct completed order count into frequency buckets.
-- Output Metrics: purchase_bucket, customer_count, pct_of_customers, total_revenue_generated
-- Business Interpretation: Evaluates customer repeat purchase dependency.
-- -----------------------------------------------------------------------------
WITH CustomerOrders AS (
    SELECT 
        customer_id,
        COUNT(DISTINCT order_id) AS order_count,
        SUM(total_amount) AS total_spend
    FROM orders
    WHERE order_status IN ('Completed', 'Shipped')
    GROUP BY customer_id
),
Bucketized AS (
    SELECT 
        customer_id,
        total_spend,
        CASE 
            WHEN order_count = 1 THEN '1 Order (One-Time Buyer)'
            WHEN order_count BETWEEN 2 AND 3 THEN '2-3 Orders (Repeat Buyer)'
            WHEN order_count BETWEEN 4 AND 6 THEN '4-6 Orders (Loyal Buyer)'
            ELSE '7+ Orders (VIP Champion)'
        END AS purchase_bucket
    FROM CustomerOrders
)
SELECT 
    purchase_bucket,
    COUNT(customer_id) AS customer_count,
    ROUND((COUNT(customer_id) * 100.0 / (SELECT COUNT(*) FROM CustomerOrders)), 2) AS pct_of_customers,
    ROUND(SUM(total_spend), 2) AS total_revenue_generated
FROM Bucketized
GROUP BY purchase_bucket
ORDER BY total_revenue_generated DESC;


-- -----------------------------------------------------------------------------
-- Business Question 7: What are the raw Recency, Frequency, and Monetary (RFM) quintile scores for active customers?
-- SQL Techniques: CTE, Window Function NTILE(5) OVER(), DATEDIFF()
-- Logic: Recency = Max Date - Customer Last Order Date. Assigns 1-5 quintiles for R, F, M.
-- Output Metrics: customer_id, recency_days, frequency_orders, monetary_spend, r_score, f_score, m_score
-- Business Interpretation: Provides underlying RFM scores for downstream customer segmentation.
-- -----------------------------------------------------------------------------
WITH MaxDatasetDate AS (
    SELECT MAX(order_date) AS max_date FROM orders
),
CustomerRFM AS (
    SELECT 
        o.customer_id,
        DATEDIFF((SELECT max_date FROM MaxDatasetDate), MAX(o.order_date)) AS recency_days,
        COUNT(DISTINCT o.order_id) AS frequency_orders,
        SUM(o.total_amount) AS monetary_spend
    FROM orders o
    WHERE o.order_status IN ('Completed', 'Shipped')
    GROUP BY o.customer_id
)
SELECT 
    customer_id,
    recency_days,
    frequency_orders,
    ROUND(monetary_spend, 2) AS monetary_spend,
    NTILE(5) OVER (ORDER BY recency_days DESC) AS r_score,
    NTILE(5) OVER (ORDER BY frequency_orders ASC) AS f_score,
    NTILE(5) OVER (ORDER BY monetary_spend ASC) AS m_score
FROM CustomerRFM
ORDER BY monetary_spend DESC
LIMIT 20;


-- -----------------------------------------------------------------------------
-- Business Question 8: What is the monthly revenue split between New Acquisition vs Returning Customers?
-- SQL Techniques: CTE, Min Order Date isolation, JOIN, CASE Classification
-- Logic: An order is 'New' if placed in the customer's first purchase month, else 'Returning'.
-- Output Metrics: order_month, new_customer_revenue, returning_customer_revenue, pct_returning_revenue
-- Business Interpretation: Measures platform reliance on new user acquisition vs retention.
-- -----------------------------------------------------------------------------
WITH FirstPurchase AS (
    SELECT 
        customer_id,
        MIN(DATE_FORMAT(order_date, '%Y-%m')) AS first_order_month
    FROM orders
    WHERE order_status IN ('Completed', 'Shipped')
    GROUP BY customer_id
),
OrderClassification AS (
    SELECT 
        DATE_FORMAT(o.order_date, '%Y-%m') AS order_month,
        o.total_amount,
        CASE 
            WHEN DATE_FORMAT(o.order_date, '%Y-%m') = fp.first_order_month THEN 'New'
            ELSE 'Returning'
        END AS customer_type
    FROM orders o
    JOIN FirstPurchase fp ON o.customer_id = fp.customer_id
    WHERE o.order_status IN ('Completed', 'Shipped')
)
SELECT 
    order_month,
    ROUND(SUM(CASE WHEN customer_type = 'New' THEN total_amount ELSE 0 END), 2) AS new_customer_revenue,
    ROUND(SUM(CASE WHEN customer_type = 'Returning' THEN total_amount ELSE 0 END), 2) AS returning_customer_revenue,
    ROUND(
        (SUM(CASE WHEN customer_type = 'Returning' THEN total_amount ELSE 0 END) * 100.0 / 
        NULLIF(SUM(total_amount), 0)), 
        2
    ) AS pct_returning_revenue
FROM OrderClassification
GROUP BY order_month
ORDER BY order_month ASC;


-- -----------------------------------------------------------------------------
-- Business Question 9: What is the average time interval (days) between a customer's 1st and 2nd purchase?
-- SQL Techniques: CTE, Window Function ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date), DATEDIFF()
-- Logic: Isolates sequence 1 and sequence 2 orders per repeat customer.
-- Output Metrics: total_repeat_customers, avg_days_to_second_purchase, min_days, max_days
-- Business Interpretation: Determines optimal timing window for post-purchase re-engagement campaigns.
-- -----------------------------------------------------------------------------
WITH OrderedPurchases AS (
    SELECT 
        customer_id,
        order_date,
        ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_date ASC) AS purchase_seq
    FROM orders
    WHERE order_status IN ('Completed', 'Shipped')
),
FirstAndSecond AS (
    SELECT 
        p1.customer_id,
        p1.order_date AS first_order_date,
        p2.order_date AS second_order_date,
        DATEDIFF(p2.order_date, p1.order_date) AS days_between
    FROM OrderedPurchases p1
    JOIN OrderedPurchases p2 ON p1.customer_id = p2.customer_id AND p2.purchase_seq = 2
    WHERE p1.purchase_seq = 1
)
SELECT 
    COUNT(customer_id) AS total_repeat_customers,
    ROUND(AVG(days_between), 1) AS avg_days_to_second_purchase,
    MIN(days_between) AS min_days,
    MAX(days_between) AS max_days
FROM FirstAndSecond;


-- -----------------------------------------------------------------------------
-- Business Question 10: What are the 30-day, 60-day, and 90-day repurchase retention rates across acquisition cohorts?
-- SQL Techniques: CTE, Acquisition Cohort Min Date, LEFT JOIN, Conditional Aggregations
-- Logic: Measures if a customer placed a subsequent order within 30, 60, or 90 days after first purchase.
-- Output Metrics: cohort_month, initial_cohort_size, retained_30d, pct_retained_30d, retained_60d, pct_retained_60d, retained_90d, pct_retained_90d
-- Business Interpretation: Tracks early customer retention drop-off across cohorts.
-- -----------------------------------------------------------------------------
WITH CohortBase AS (
    SELECT 
        customer_id,
        MIN(order_date) AS first_order_date,
        DATE_FORMAT(MIN(order_date), '%Y-%m') AS cohort_month
    FROM orders
    WHERE order_status IN ('Completed', 'Shipped')
    GROUP BY customer_id
),
SubsequentOrders AS (
    SELECT DISTINCT
        cb.customer_id,
        cb.cohort_month,
        o.order_date,
        DATEDIFF(o.order_date, cb.first_order_date) AS days_since_first
    FROM CohortBase cb
    JOIN orders o ON cb.customer_id = o.customer_id
    WHERE o.order_status IN ('Completed', 'Shipped')
      AND DATEDIFF(o.order_date, cb.first_order_date) > 0
)
SELECT 
    cb.cohort_month,
    COUNT(DISTINCT cb.customer_id) AS initial_cohort_size,
    COUNT(DISTINCT CASE WHEN so.days_since_first BETWEEN 1 AND 30 THEN cb.customer_id END) AS retained_30d,
    ROUND(COUNT(DISTINCT CASE WHEN so.days_since_first BETWEEN 1 AND 30 THEN cb.customer_id END) * 100.0 / COUNT(DISTINCT cb.customer_id), 1) AS pct_retained_30d,
    COUNT(DISTINCT CASE WHEN so.days_since_first BETWEEN 1 AND 60 THEN cb.customer_id END) AS retained_60d,
    ROUND(COUNT(DISTINCT CASE WHEN so.days_since_first BETWEEN 1 AND 60 THEN cb.customer_id END) * 100.0 / COUNT(DISTINCT cb.customer_id), 1) AS pct_retained_60d,
    COUNT(DISTINCT CASE WHEN so.days_since_first BETWEEN 1 AND 90 THEN cb.customer_id END) AS retained_90d,
    ROUND(COUNT(DISTINCT CASE WHEN so.days_since_first BETWEEN 1 AND 90 THEN cb.customer_id END) * 100.0 / COUNT(DISTINCT cb.customer_id), 1) AS pct_retained_90d
FROM CohortBase cb
LEFT JOIN SubsequentOrders so ON cb.customer_id = so.customer_id
GROUP BY cb.cohort_month
ORDER BY cb.cohort_month ASC;


-- -----------------------------------------------------------------------------
-- Business Question 11: What is the customer revenue concentration across customer spend deciles (Pareto Analysis)?
-- SQL Techniques: CTE, Window Function NTILE(10) OVER(), SUM() OVER()
-- Logic: Groups customers into 10 deciles by spend to evaluate top-tier revenue concentration.
-- Output Metrics: spend_decile, customer_count, decile_revenue, pct_of_total_revenue, cumulative_revenue_pct
-- Business Interpretation: Quantifies platform vulnerability to high-value customer churn.
-- -----------------------------------------------------------------------------
WITH CustomerSpend AS (
    SELECT 
        customer_id,
        SUM(total_amount) AS total_spend
    FROM orders
    WHERE order_status IN ('Completed', 'Shipped')
    GROUP BY customer_id
),
DeciledSpend AS (
    SELECT 
        customer_id,
        total_spend,
        NTILE(10) OVER (ORDER BY total_spend DESC) AS spend_decile
    FROM CustomerSpend
),
DecileSummary AS (
    SELECT 
        spend_decile,
        COUNT(customer_id) AS customer_count,
        SUM(total_spend) AS decile_revenue
    FROM DeciledSpend
    GROUP BY spend_decile
)
SELECT 
    spend_decile,
    customer_count,
    ROUND(decile_revenue, 2) AS decile_revenue,
    ROUND((decile_revenue * 100.0 / (SELECT SUM(total_spend) FROM CustomerSpend)), 2) AS pct_of_total_revenue,
    ROUND(
        SUM(decile_revenue) OVER (ORDER BY spend_decile ASC) * 100.0 / 
        (SELECT SUM(total_spend) FROM CustomerSpend), 
        2
    ) AS cumulative_revenue_pct
FROM DecileSummary
ORDER BY spend_decile ASC;


-- =============================================================================
-- SECTION 3: PRODUCT & BASKET ANALYTICS
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Business Question 12: What are the Top 10 revenue-generating products vs Bottom 5 underperformers?
-- SQL Techniques: CTE, JOIN, Window Function DENSE_RANK() OVER(), UNION ALL
-- Logic: Ranks products by gross sales to identify catalog leaders and low-velocity items.
-- Output Metrics: rank_group, product_rank, product_name, category_name, total_units_sold, total_revenue
-- Business Interpretation: Informs merchandising decisions on featured promotions vs SKU pruning.
-- -----------------------------------------------------------------------------
WITH ProductRevenue AS (
    SELECT 
        p.product_id,
        p.product_name,
        cat.category_name,
        SUM(oi.quantity) AS total_units_sold,
        SUM(oi.item_total) AS total_revenue
    FROM order_items oi
    JOIN orders o ON oi.order_id = o.order_id
    JOIN products p ON oi.product_id = p.product_id
    JOIN categories cat ON p.category_id = cat.category_id
    WHERE o.order_status IN ('Completed', 'Shipped')
    GROUP BY p.product_id, p.product_name, cat.category_name
),
RankedProducts AS (
    SELECT 
        product_id,
        product_name,
        category_name,
        total_units_sold,
        total_revenue,
        DENSE_RANK() OVER (ORDER BY total_revenue DESC) AS top_rank,
        DENSE_RANK() OVER (ORDER BY total_revenue ASC) AS bottom_rank
    FROM ProductRevenue
)
SELECT 
    'Top Performer' AS rank_group,
    top_rank AS product_rank,
    product_name,
    category_name,
    total_units_sold,
    ROUND(total_revenue, 2) AS total_revenue
FROM RankedProducts
WHERE top_rank <= 10

UNION ALL

SELECT 
    'Bottom Underperformer' AS rank_group,
    bottom_rank AS product_rank,
    product_name,
    category_name,
    total_units_sold,
    ROUND(total_revenue, 2) AS total_revenue
FROM RankedProducts
WHERE bottom_rank <= 5
ORDER BY rank_group DESC, product_rank ASC;


-- -----------------------------------------------------------------------------
-- Business Question 13: What is the sales velocity (units/day) and estimated stock run-out risk for products?
-- SQL Techniques: CTE, DATEDIFF(), Division, Stock-to-Sales Ratio calculation
-- Logic: Run-out days = Current Stock Quantity / Daily Sales Velocity.
-- Output Metrics: product_name, category_name, stock_quantity, units_sold, daily_velocity, days_inventory_remaining, stockout_risk_level
-- Business Interpretation: Alert mechanism for replenishment and supply chain optimization.
-- -----------------------------------------------------------------------------
WITH VelocityBase AS (
    SELECT 
        p.product_id,
        p.product_name,
        cat.category_name,
        p.stock_quantity,
        SUM(oi.quantity) AS total_units_sold,
        DATEDIFF(MAX(o.order_date), MIN(o.order_date)) AS sales_days_span
    FROM order_items oi
    JOIN orders o ON oi.order_id = o.order_id
    JOIN products p ON oi.product_id = p.product_id
    JOIN categories cat ON p.category_id = cat.category_id
    WHERE o.order_status IN ('Completed', 'Shipped')
    GROUP BY p.product_id, p.product_name, cat.category_name, p.stock_quantity
)
SELECT 
    product_name,
    category_name,
    stock_quantity,
    total_units_sold,
    ROUND(total_units_sold / NULLIF(sales_days_span, 0), 2) AS daily_velocity,
    ROUND(stock_quantity / NULLIF((total_units_sold / NULLIF(sales_days_span, 0)), 0), 0) AS days_inventory_remaining,
    CASE 
        WHEN (stock_quantity / NULLIF((total_units_sold / NULLIF(sales_days_span, 0)), 0)) < 30 THEN 'CRITICAL: Stockout Imminent (<30 Days)'
        WHEN (stock_quantity / NULLIF((total_units_sold / NULLIF(sales_days_span, 0)), 0)) BETWEEN 30 AND 90 THEN 'WARNING: Medium Risk (30-90 Days)'
        ELSE 'HEALTHY: Adequate Inventory (>90 Days)'
    END AS stockout_risk_level
FROM VelocityBase
ORDER BY days_inventory_remaining ASC
LIMIT 15;


-- -----------------------------------------------------------------------------
-- Business Question 14: What is the category performance matrix comparing revenue, average discount %, and profit margin?
-- SQL Techniques: Multi-table JOIN, Aggregations, Average Discount % calculation
-- Logic: Evaluates whether discounting is cannibalizing gross margins across categories.
-- Output Metrics: category_name, total_orders, gross_revenue, total_discount_given, avg_discount_pct, net_profit, margin_pct
-- Business Interpretation: Detects over-discounted categories requiring price elasticity adjustments.
-- -----------------------------------------------------------------------------
SELECT 
    cat.category_name,
    COUNT(DISTINCT o.order_id) AS total_orders,
    ROUND(SUM(oi.item_total + oi.discount_amount), 2) AS gross_list_revenue,
    ROUND(SUM(oi.discount_amount), 2) AS total_discount_given,
    ROUND(AVG(oi.discount_amount / NULLIF((oi.unit_price * oi.quantity), 0)) * 100, 2) AS avg_discount_pct,
    ROUND(SUM(oi.item_total), 2) AS net_revenue,
    ROUND(SUM(oi.item_total) - SUM(p.cost_price * oi.quantity), 2) AS net_profit,
    ROUND(((SUM(oi.item_total) - SUM(p.cost_price * oi.quantity)) / NULLIF(SUM(oi.item_total), 0)) * 100, 2) AS margin_pct
FROM order_items oi
JOIN orders o ON oi.order_id = o.order_id
JOIN products p ON oi.product_id = p.product_id
JOIN categories cat ON p.category_id = cat.category_id
WHERE o.order_status IN ('Completed', 'Shipped')
GROUP BY cat.category_name
ORDER BY net_profit DESC;


-- -----------------------------------------------------------------------------
-- Business Question 15: Which product pairs are most frequently cross-purchased together in the same basket?
-- SQL Techniques: Self-JOIN on order_items (oi1.order_id = oi2.order_id AND oi1.product_id < oi2.product_id)
-- Logic: Identifies item pairs appearing together in valid orders to calculate co-occurrence count.
-- Output Metrics: product_A, product_B, co_purchase_count
-- Business Interpretation: Drives cross-selling recommendations, bundle creation, and checkout add-ons.
-- -----------------------------------------------------------------------------
SELECT 
    p1.product_name AS product_A,
    p2.product_name AS product_B,
    COUNT(DISTINCT oi1.order_id) AS co_purchase_count
FROM order_items oi1
JOIN order_items oi2 ON oi1.order_id = oi2.order_id AND oi1.product_id < oi2.product_id
JOIN orders o ON oi1.order_id = o.order_id
JOIN products p1 ON oi1.product_id = p1.product_id
JOIN products p2 ON oi2.product_id = p2.product_id
WHERE o.order_status IN ('Completed', 'Shipped')
GROUP BY p1.product_name, p2.product_name
HAVING COUNT(DISTINCT oi1.order_id) >= 5
ORDER BY co_purchase_count DESC
LIMIT 15;


-- -----------------------------------------------------------------------------
-- Business Question 16: What is the distribution of basket sizes (item count per order) and order value?
-- SQL Techniques: CTE order-level aggregation, CASE classification
-- Logic: Aggregates total line items per order, then groups by basket size category.
-- Output Metrics: basket_size_category, total_orders, pct_of_orders, total_revenue, avg_order_value
-- Business Interpretation: Measures multi-item basket conversion and basket-building initiatives.
-- -----------------------------------------------------------------------------
WITH OrderBasketSizes AS (
    SELECT 
        o.order_id,
        SUM(oi.quantity) AS total_items_in_order,
        o.total_amount
    FROM orders o
    JOIN order_items oi ON o.order_id = oi.order_id
    WHERE o.order_status IN ('Completed', 'Shipped')
    GROUP BY o.order_id, o.total_amount
),
BasketBuckets AS (
    SELECT 
        order_id,
        total_amount,
        CASE 
            WHEN total_items_in_order = 1 THEN '1 Item (Single Product Basket)'
            WHEN total_items_in_order BETWEEN 2 AND 3 THEN '2-3 Items (Small Basket)'
            WHEN total_items_in_order BETWEEN 4 AND 6 THEN '4-6 Items (Medium Basket)'
            ELSE '7+ Items (Large Multi-Item Basket)'
        END AS basket_size_category
    FROM OrderBasketSizes
)
SELECT 
    basket_size_category,
    COUNT(order_id) AS total_orders,
    ROUND(COUNT(order_id) * 100.0 / (SELECT COUNT(*) FROM BasketBuckets), 2) AS pct_of_orders,
    ROUND(SUM(total_amount), 2) AS total_revenue,
    ROUND(AVG(total_amount), 2) AS avg_order_value
FROM BasketBuckets
GROUP BY basket_size_category
ORDER BY total_revenue DESC;


-- =============================================================================
-- SECTION 4: OPERATIONS & FULFILLMENT ANALYTICS
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Business Question 17: How do shipping carriers compare on delivery SLA compliance and delay rates?
-- SQL Techniques: JOIN (orders, shipping), DATEDIFF(), Conditional Aggregations
-- Logic: Delay = DATEDIFF(actual_delivery_date, estimated_delivery_date) > 0.
-- Output Metrics: carrier, total_shipments, delivered_on_time, delivered_delayed, avg_delay_days, sla_compliance_pct
-- Business Interpretation: Evaluates carrier SLA performance to renegotiate logistics contracts.
-- -----------------------------------------------------------------------------
SELECT 
    s.carrier,
    COUNT(s.shipping_id) AS total_shipments,
    COUNT(CASE WHEN s.delivery_status = 'Delivered On-Time' THEN 1 END) AS delivered_on_time,
    COUNT(CASE WHEN s.delivery_status = 'Delivered Delayed' THEN 1 END) AS delivered_delayed,
    ROUND(AVG(CASE WHEN DATEDIFF(s.actual_delivery_date, s.estimated_delivery_date) > 0 
                   THEN DATEDIFF(s.actual_delivery_date, s.estimated_delivery_date) END), 1) AS avg_delay_days,
    ROUND(
        COUNT(CASE WHEN s.delivery_status = 'Delivered On-Time' THEN 1 END) * 100.0 / 
        NULLIF(COUNT(CASE WHEN s.actual_delivery_date IS NOT NULL THEN 1 END), 0), 
        2
    ) AS sla_compliance_pct
FROM shipping s
JOIN orders o ON s.order_id = o.order_id
WHERE s.actual_delivery_date IS NOT NULL
GROUP BY s.carrier
ORDER BY sla_compliance_pct DESC;


-- -----------------------------------------------------------------------------
-- Business Question 18: What is the cancellation and refund rate breakdown across payment methods and order statuses?
-- SQL Techniques: JOIN (orders, payments), GROUP BY, Percentage calculations
-- Logic: Computes the proportion of orders cancelled or refunded relative to total order volume per payment method.
-- Output Metrics: payment_method, total_orders, completed_orders, cancelled_orders, refunded_orders, cancellation_rate_pct, refund_rate_pct
-- Business Interpretation: Uncovers financial friction or gateway drop-off issues per payment channel.
-- -----------------------------------------------------------------------------
SELECT 
    p.payment_method,
    COUNT(DISTINCT o.order_id) AS total_orders,
    COUNT(DISTINCT CASE WHEN o.order_status = 'Completed' THEN o.order_id END) AS completed_orders,
    COUNT(DISTINCT CASE WHEN o.order_status = 'Cancelled' THEN o.order_id END) AS cancelled_orders,
    COUNT(DISTINCT CASE WHEN o.order_status = 'Refunded' THEN o.order_id END) AS refunded_orders,
    ROUND(
        COUNT(DISTINCT CASE WHEN o.order_status = 'Cancelled' THEN o.order_id END) * 100.0 / 
        NULLIF(COUNT(DISTINCT o.order_id), 0), 
        2
    ) AS cancellation_rate_pct,
    ROUND(
        COUNT(DISTINCT CASE WHEN o.order_status = 'Refunded' THEN o.order_id END) * 100.0 / 
        NULLIF(COUNT(DISTINCT o.order_id), 0), 
        2
    ) AS refund_rate_pct
FROM orders o
JOIN payments p ON o.order_id = p.order_id
GROUP BY p.payment_method
ORDER BY total_orders DESC;
